/*
 * Focused probe for the ported grub_strlcpy() helper.
 *
 * Includes the real target include/grub/misc.h (via -I <target>/include)
 * and exercises the documented strlcpy semantics:
 *   - returns strlen(src)
 *   - always NUL-terminates dest when size != 0
 *   - copies at most size-1 bytes
 *   - leaves dest untouched when size == 0
 *
 * Compiled against the patched candidate header and against the
 * unpatched baseline header to demonstrate the compile-time exposure.
 */
#include <grub/misc.h>

#include <stdio.h>
#include <string.h>

static int failures;

static void
check_str (const char *name, const char *got, size_t gotret,
           const char *exp, size_t expret)
{
  if (strcmp (got, exp) != 0 || gotret != expret)
    {
      printf ("FAIL %s: got='%s' ret=%zu expected='%s' ret=%zu\n",
              name, got, gotret, exp, expret);
      failures++;
    }
  else
    printf ("ok   %s: '%s' ret=%zu\n", name, got, gotret);
}

int
main (void)
{
  char buf[64];
  grub_size_t r;

  memset (buf, 'X', sizeof (buf));
  r = grub_strlcpy (buf, "hello", sizeof (buf));
  check_str ("fits", buf, r, "hello", 5);

  memset (buf, 'X', sizeof (buf));
  r = grub_strlcpy (buf, "hello world", 6);
  check_str ("truncate", buf, r, "hello", 11);

  memset (buf, 'X', sizeof (buf));
  r = grub_strlcpy (buf, "abc", 1);
  check_str ("size1", buf, r, "", 3);

  memset (buf, 'X', sizeof (buf));
  r = grub_strlcpy (buf, "abc", 0);
  if (r != 3 || buf[0] != 'X')
    {
      printf ("FAIL size0: ret=%zu buf[0]='%c'\n", (size_t) r, buf[0]);
      failures++;
    }
  else
    printf ("ok   size0: untouched ret=%zu\n", (size_t) r);

  memset (buf, 'X', sizeof (buf));
  r = grub_strlcpy (buf, "", sizeof (buf));
  check_str ("empty", buf, r, "", 0);

  /* Boundary: exactly size-1 bytes must be copied plus NUL. */
  memset (buf, 'X', sizeof (buf));
  r = grub_strlcpy (buf, "abcd", 5);
  check_str ("exact-fit-minus-one", buf, r, "abcd", 4);

  if (failures)
    {
      printf ("%d FAILURE(S)\n", failures);
      return 1;
    }
  printf ("ALL PASS\n");
  return 0;
}

